"""Desktop collapse, persistent mobile shell, independent drawer scroll, consistent titles and first paint of Personal passes."""
import asyncio
from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);errors=[]
  async def page(width,height):
   c=await b.new_context(viewport=dict(width=width,height=height));await c.route('https://**/*',lambda r:r.abort());p=await c.new_page();p.on('pageerror',lambda e:errors.append(str(e)));await p.goto(H+'/login');await p.locator('.sicip-login-institute').wait_for();a=await p.locator('.sicip-login-institute').bounding_box();z=await p.locator('.sicip-login-ooad').bounding_box();assert z['y']>=a['y']+a['height']-1;await p.locator('input[type=text]').first.fill('TESTADMIN');await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('.sicip-app-header').wait_for();await p.wait_for_function('document.querySelector("[data-personal-vacaciones]")');return p
  p=await page(1440,900);nav=p.locator('nav.sidebar');assert await nav.is_visible();initial=await p.locator('main').bounding_box();toggle=p.locator('[aria-controls="sicip-sidebar"]');await toggle.click();await nav.wait_for(state='hidden');wide=await p.locator('main').bounding_box();assert wide['width']-initial['width']>=250 and wide['x']==0;await toggle.click();await nav.wait_for();await nav.get_by_role('button',name='Administración',exact=True).click();await p.locator('.admin-unified-tabs').wait_for();assert await nav.is_visible();await p.locator('main .sicip-page-heading').first.wait_for();print('Windows: menú completo colapsa, amplía el contenido y conserva selección al navegar.',flush=True)
  p=await page(390,640);nav=p.locator('nav.sidebar');toggle=p.locator('[aria-controls="sicip-sidebar"]');assert not await nav.is_visible();head=p.locator('.sicip-app-header');assert (await head.bounding_box())['height']==60;assert not await p.locator('.sicip-header-user').is_visible();await toggle.click();await nav.wait_for();assert (await nav.bounding_box())['y']==60
  await p.locator('[data-sicip-depto-btn]').click();await p.locator('[data-tools-toggle]').click();await nav.get_by_role('button',name='Jefe de Servicio',exact=False).first.click();await p.locator('[data-sicip-solicitudes-btn]').click();assert await nav.is_visible();await p.wait_for_timeout(180);metrics=await nav.evaluate('(n)=>({scroll:n.scrollHeight,client:n.clientHeight})');assert metrics['scroll']>metrics['client'],metrics;await nav.hover();await p.mouse.wheel(0,600);await p.wait_for_timeout(160);assert await nav.evaluate('(n)=>n.scrollTop')>0;bottom=await nav.evaluate('(n)=>n.scrollTop');await p.mouse.wheel(0,-300);await p.wait_for_timeout(120);assert await nav.evaluate('(n)=>n.scrollTop')<bottom;assert (await head.bounding_box())['y']==0;assert await p.evaluate('window.scrollY')==0;print('Celular: barra de 60px, nombre/rol ocultos, menú desplaza de forma independiente debajo de la barra.',flush=True)
  # Delayed roster must never expose the worker's form in Personal's module.
  await p.context.add_init_script('''if(location.pathname.startsWith('/pases')){window.__wrongPassPaint=[];const observe=()=>{const title=document.getElementById('moduleTitle'),form=document.getElementById('passForm');if(title&&form&&form.getClientRects().length&&!title.textContent.includes('Personal'))__wrongPassPaint.push(title.textContent);};new MutationObserver(observe).observe(document,{childList:true,subtree:true,attributes:true});setInterval(observe,20);}''')
  async def delay(route):await asyncio.sleep(.6);await route.continue_()
  await p.route('**/api/base/datasets/**',delay)
  await p.locator('[data-sicip-depto-sub=tramite-pases]').click();await nav.wait_for(state='hidden');frame=p.frame_locator('#sicip-pases-view iframe');await frame.locator('html[data-pases-ready="1"]').wait_for();assert 'Personal' in await frame.locator('#moduleTitle').inner_text();assert await frame.locator('[data-pass-path]').count()==2;assert await p.locator('#sicip-pases-view iframe').evaluate('(f)=>f.contentWindow.__wrongPassPaint.length')==0;assert (await head.bounding_box())['y']==0
  await p.locator('main').hover();await p.mouse.wheel(0,1200);await p.wait_for_timeout(200);assert (await head.bounding_box())['y']==0;assert await p.evaluate('window.scrollY')==0;assert await p.locator('main').evaluate('(m)=>m.scrollTop')>0;assert await frame.locator('.hero img').count()==0;print('Pases de Personal: carga sin vista de usuario y desplazamiento conserva encabezado.',flush=True)
  for selector,panel in [('[data-personal-vacaciones]','[data-sicip-module-panel=vacaciones]'),('[data-personal-normativas]','[data-sicip-module-panel=normativas]'),('[data-access-id="personal.herramientas.nivelacion"]','[data-sicip-module-panel=herramientas-personal]')]:
   await toggle.click();await nav.wait_for();await p.locator(selector).click();await nav.wait_for(state='hidden');await p.locator(panel).wait_for();heading=p.locator(panel+' .sicip-page-heading');await heading.wait_for();style=await heading.evaluate('(e)=>({bg:getComputedStyle(e).backgroundColor,border:getComputedStyle(e).borderLeftWidth,size:getComputedStyle(e.querySelector("h1,h2")).fontSize})');assert style=={'bg':'rgb(241, 246, 243)','border':'4px','size':'22px'},style;await p.locator('main').evaluate('(e)=>e.scrollTop=e.scrollHeight');assert (await head.bounding_box())['y']==0;assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1')
  await p.wait_for_function('window.SICIPPerfil');await p.locator('.sicip-profile-icon').click();await p.locator('[data-profile-dialog]').wait_for();await p.locator('[data-profile-close]').click();await p.screenshot(path='/tmp/sicip-navigation-mobile.png');assert not errors,errors;await b.close();print('Vacaciones, Normativas y Herramientas: títulos uniformes y barra siempre visible; login en dos líneas.',flush=True)
asyncio.run(main())
